window.ARH_LESSONS=(window.ARH_LESSONS||[]).concat([
{"id": 300, "title": "Сложение с переходом через десяток", "ico": "➕", "src": "Начальная школа · 1 класс · Сложение и вычитание в пределах 20", "subj": "jun", "explain": ["Перед нами пример 8 + 5: сумма больше 10. Способ Архимеда — «дополняем до десятка».", "Дополняем 8 до 10: не хватает 2. Забираем эти 2 у пятёрки: 5 = 2 + 3.", "Теперь легко: 8 + 2 = 10, и прибавляем оставшиеся 3 → 10 + 3 = 13. Значит, 8 + 5 = 13.", "Вычитание тоже идёт через десяток: 14 − 6. Сначала 14 − 4 = 10, затем 10 − 2 = 8."], "check": {"q": "Чему равно 7 + 6?", "choices": ["12", "13", "14", "15"], "ans": 1, "exp": "Дополняем 7 до 10 (+3); у шестёрки остаётся 3: 10 + 3 = 13."}, "tasks": [{"q": "Чему равно 9 + 4?", "kind": "unit", "ans": 13, "tol": 0, "hints": ["Дополни 9 до 10.", "9 + 1 = 10, осталось 3: 10 + 3 = 13."], "sol": "9 + 4 = 13"}, {"q": "Чему равно 12 − 5?", "kind": "choice", "choices": ["6", "7", "8", "9"], "ans": 1, "tol": 0, "hints": ["Сначала 12 − 2 = 10.", "10 − 3 = 7."], "sol": "12 − 5 = 7"}]},
{"id": 301, "title": "Числа 11–20: десятки и единицы", "ico": "🔟", "src": "Начальная школа · 1 класс · Нумерация чисел второго десятка", "subj": "jun", "explain": ["После 10 идут числа второго десятка: 11, 12, …, 20. Каждое — это 1 десяток и ещё несколько единиц.", "Разложим 17: 17 = 10 + 7 — один десяток и семь единиц. Название подсказывает: «сем-на-дцать».", "Ещё примеры: 14 = 10 + 4, 19 = 10 + 9, а 20 — это уже два десятка: 10 + 10.", "Тренируемся называть число по составу: 1 десяток и 6 единиц — это 16."], "check": {"q": "Сколько десятков и единиц в числе 16?", "choices": ["1 десяток и 6 единиц", "6 десятков и 1 единица", "16 десятков", "1 десяток и 16 единиц"], "ans": 0, "exp": "16 = 10 + 6: один десяток и шесть единиц."}, "tasks": [{"q": "Чему равно 10 + 7?", "kind": "unit", "ans": 17, "tol": 0, "hints": ["Один десяток и семь единиц.", "10 + 7 = 17."], "sol": "10 + 7 = 17"}, {"q": "Какое число состоит из 1 десятка и 4 единиц?", "kind": "choice", "choices": ["14", "41", "40", "4"], "ans": 0, "tol": 0, "hints": ["1 десяток = 10.", "10 + 4 = 14."], "sol": "14"}]},
{"id": 302, "title": "Числовые и буквенные выражения", "ico": "🔤", "src": "Начальная школа · 1 класс · Выражения с буквой", "subj": "jun", "explain": ["Выражение — пример с числами и знаками: 4 + 3. Если вместо числа поставить букву, получится буквенное выражение: a + 3.", "Буква — это «окошко», в которое подставляют разные числа. Если a = 5, то a + 3 = 5 + 3 = 8.", "Подставим другое число: a = 7 → a + 3 = 10. Одно выражение — много разных ответов!", "Главное — аккуратно подставить число вместо буквы и посчитать."], "check": {"q": "Найди значение a + 2, если a = 6", "choices": ["8", "4", "62", "12"], "ans": 0, "exp": "Подставляем: 6 + 2 = 8."}, "tasks": [{"q": "Найди значение b − 3, если b = 9", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Поставь 9 вместо b.", "9 − 3 = 6."], "sol": "b − 3 = 9 − 3 = 6"}, {"q": "Чему равно x + 5, если x = 4?", "kind": "choice", "choices": ["45", "9", "1", "54"], "ans": 1, "tol": 0, "hints": ["Поставь 4 вместо x.", "4 + 5 = 9."], "sol": "9"}]},
{"id": 303, "title": "Уравнения «часть–целое»", "ico": "⚖️", "src": "Начальная школа · 1 класс · Уравнения вида a+x=b, x−a=b, a−x=b", "subj": "jun", "explain": ["В сундуке Архимеда целое собрано из частей. Правило: целое = часть + часть, часть = целое − другая часть.", "Уравнение x + 3 = 8: x и 3 — части, 8 — целое. Ищем часть: x = 8 − 3 = 5.", "Уравнение 8 − x = 3: x — часть, которую отняли: x = 8 − 3 = 5.", "Всегда проверяй: 5 + 3 = 8 ✔ и 8 − 5 = 3 ✔."], "check": {"q": "Реши: x + 4 = 9", "choices": ["5", "4", "13", "9"], "ans": 0, "exp": "x — часть: x = 9 − 4 = 5."}, "tasks": [{"q": "Реши: 8 − x = 3", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Целое 8, отняли x, осталось 3.", "x = 8 − 3 = 5."], "sol": "8 − 5 = 3"}, {"q": "Реши: x − 2 = 7", "kind": "choice", "choices": ["5", "9", "2", "14"], "ans": 1, "tol": 0, "hints": ["x — целое: целое = часть + часть.", "x = 7 + 2 = 9."], "sol": "9"}]},
{"id": 304, "title": "Величины: см, дм, кг, литр", "ico": "📏", "src": "Начальная школа · 1 класс · Длина, масса, вместимость", "subj": "jun", "explain": ["Длину измеряют в сантиметрах (см) и дециметрах (дм). В одном дециметре 10 сантиметров: 1 дм = 10 см.", "Массу — в килограммах (кг): пакет яблок весит 2 кг. Вместимость — в литрах (л): банка сока — 1 л.", "Сравниваем величины: что больше — 1 дм или 9 см? 1 дм = 10 см, значит, 1 дм > 9 см.", "Запомни пары: 1 дм = 10 см; 1 м = 10 дм (понадобится позже)."], "check": {"q": "Сколько сантиметров в 1 дециметре?", "choices": ["10", "100", "1", "20"], "ans": 0, "exp": "1 дм = 10 см."}, "tasks": [{"q": "3 дм = … см", "kind": "unit", "ans": 30, "tol": 0, "hints": ["В 1 дм — 10 см.", "3 · 10 = 30 см."], "sol": "3 дм = 30 см"}, {"q": "Что измеряют в литрах?", "kind": "choice", "choices": ["длину", "массу", "вместимость", "время"], "ans": 2, "tol": 0, "hints": ["Литр — про жидкости.", "Банка, ведро, канистра — вместимость в литрах."], "sol": "вместимость"}]},
{"id": 305, "title": "Линии, отрезок, ломаная", "ico": "📐", "src": "Начальная школа · 1 класс · Геометрия: линии и фигуры", "subj": "jun", "explain": ["Прямая линия не имеет ни начала, ни конца — её можно продолжать бесконечно в обе стороны.", "Отрезок — часть прямой между двумя точками: у него есть начало и конец, его длину измеряют линейкой.", "Ломаная — несколько отрезков, соединённых друг за другом (как заборчик или молния). Каждый отрезок ломаной — звено.", "Круг, квадрат, треугольник нарисованы отрезками? Нет: у круга граница плавная, а у квадрата и треугольника — из отрезков."], "check": {"q": "Какая линия не имеет ни начала, ни конца?", "choices": ["прямая", "отрезок", "луч", "ломаная"], "ans": 0, "exp": "Прямую можно продолжать бесконечно в обе стороны."}, "tasks": [{"q": "Сколько концов у отрезка?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Отрезок ограничен двумя точками.", "Начало и конец — два конца."], "sol": "2"}, {"q": "Из чего состоит ломаная?", "kind": "choice", "choices": ["из отрезков", "из кругов", "из точек без отрезков", "из лучей"], "ans": 0, "tol": 0, "hints": ["Звенья ломаной — отрезки.", "Отрезки, соединённые друг за другом."], "sol": "из отрезков"}]},
{"id": 306, "title": "Закономерности и таблицы", "ico": "🔢", "src": "Начальная школа · 1 класс · Логика: ряды, таблицы, высказывания", "subj": "jun", "explain": ["Волшебная лестница Архимеда: 1, 3, 5, … Какое число дальше? Видим правило: каждый раз прибавляем 2.", "Закономерность — правило, по которому числа или фигуры повторяются. Нашёл правило — продолжи ряд!", "Таблицы помогают не запутаться: записываем числа по строкам и столбцам и смотрим, как меняется каждый ряд.", "Всегда проверяй: работает ли правило на каждом шаге ряда."], "check": {"q": "Продолжи ряд: 2, 4, 6, …", "choices": ["7", "8", "9", "10"], "ans": 1, "exp": "Правило «+2»: 6 + 2 = 8."}, "tasks": [{"q": "Какое число пропущено: 5, 10, 15, …, 25?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Правило «+5».", "15 + 5 = 20."], "sol": "20"}, {"q": "Продолжи: 10, 8, 6, …", "kind": "choice", "choices": ["4", "5", "7", "8"], "ans": 0, "tol": 0, "hints": ["Правило «−2».", "6 − 2 = 4."], "sol": "4"}]},
{"id": 307, "title": "Логика: кто есть кто", "ico": "🕵️", "src": "Начальная школа · 1 класс · Олимп-1: логические задачи", "subj": "jun", "explain": ["Трое ребят — Антон, Боря и Вера. Один любит кошек, другой собак, третий — рыбок.", "Известно: Вера любит собак, Антон НЕ любит кошек, Боря НЕ любит рыбок. Кто любит кошек?", "Рассуждаем: Вера — собаки. Остались кошки и рыбки для Антона и Бори. Антон не кошки → рыбки. Боре достаются кошки!", "Секрет: не спешить, а заполнять таблицу: имя × любимец, ставить ✔ и ✘."], "check": {"q": "Вера любит собак, Антон не любит кошек, Боря не любит рыбок. Кто любит кошек?", "choices": ["Антон", "Боря", "Вера", "нельзя узнать"], "ans": 1, "exp": "Вера — собаки; Антон не кошки → рыбки; остаётся Боря — кошки."}, "tasks": [{"q": "Маша и Дима: один рисует, другой поёт. Маша не поёт. Кто поёт?", "kind": "choice", "choices": ["Маша", "Дима", "оба", "никто"], "ans": 1, "tol": 0, "hints": ["Маша не поёт — значит, рисует.", "Диме остаётся пение."], "sol": "Дима"}, {"q": "Котёнок, щенок и хомяк живут в клетках: серой, белой и рыжей. Котёнок — в рыжей, щенок — не в белой. Где хомяк?", "kind": "choice", "choices": ["в серой", "в белой", "в рыжей", "нельзя узнать"], "ans": 1, "tol": 0, "hints": ["Котёнок — рыжая, остались серая и белая.", "Щенок не в белой → серая; хомяк — белая."], "sol": "хомяк в белой"}]},
{"id": 308, "title": "Задачи-смекалки", "ico": "🎩", "src": "Начальная школа · 1 класс · Олимп-1: смекалка", "subj": "jun", "explain": ["У Архимеда 3 яблока и 3 друга. Как дать каждому по яблоку, чтобы одно осталось в мешке? Отдать последнему яблоко вместе с мешком!", "Смекалка — умение увидеть необычное решение. Сначала подумай, о чём задача, а потом считай.", "Пример на внимание: у каждого котёнка 2 уха. Сколько ушей у трёх котят? 3 · 2 = 6.", "Иногда ответ прячется в словах, а не в числах — читай условие до конца!"], "check": {"q": "Сколько ушей у трёх котят?", "choices": ["3", "6", "5", "8"], "ans": 1, "exp": "У каждого котёнка 2 уха: 3 · 2 = 6."}, "tasks": [{"q": "Сколько лап у двух уток?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["У каждой утки 2 лапы.", "2 + 2 = 4."], "sol": "4"}, {"q": "Три брата, и у каждого одна сестра. Сколько детей в семье?", "kind": "choice", "choices": ["3", "4", "6", "2"], "ans": 1, "tol": 0, "hints": ["Сестра у братьев общая.", "3 брата + 1 сестра = 4."], "sol": "4"}]},
{"id": 309, "title": "Игры: выигрышная стратегия", "ico": "🎮", "src": "Начальная школа · 1 класс · Олимп-1: игры и симметрия", "subj": "jun", "explain": ["Игра: на столе 6 камешков. За ход берут 1 или 2. Проигрывает тот, кто не может сходить.", "Секрет — «дополнение до 3»: если противник берёт 1, мы берём 2; если 2 — берём 1. Вместе всегда 3!", "Первый берёт 1 или 2, второй дополняет до 3: 6 = 3 + 3. Последним ходит второй — он и выигрывает.", "Такой приём называют симметричной (парной) стратегией: повторяй ходы противника по правилу."], "check": {"q": "На столе 6 камешков, за ход берут 1 или 2. Кто выиграет при правильной игре?", "choices": ["первый", "второй", "никто", "нельзя узнать"], "ans": 1, "exp": "Первый берёт 1 или 2 — второй дополняет до 3 и забирает последний камешек."}, "tasks": [{"q": "Сколько камешков забирают за пару ходов «противник 1 + мы 2»?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["1 + 2 = 3.", "Пара ходов всегда уносит 3 камешка."], "sol": "3"}, {"q": "На столе 4 камешка, берут 1 или 2. Сколько взять первым, чтобы выиграть?", "kind": "choice", "choices": ["1", "2", "3", "4"], "ans": 0, "tol": 0, "hints": ["После твоего хода должно остаться 3.", "Возьми 1: останется 3 — «ловушка», второй обречён."], "sol": "взять 1"}]},
{"id": 310, "title": "Перебор и простые шифры", "ico": "🗝️", "src": "Начальная школа · 1 класс · Олимп-1: перебор, кодирование", "subj": "jun", "explain": ["Архимед задумал число от 1 до 5: оно больше 2 и меньше 5. Подходят 3 и 4 — нужны ещё условия!", "Перебор — проверяем все варианты по очереди и отбрасываем неподходящие. Записывай варианты, чтобы ничего не пропустить.", "Секретный код: 🍎 = 1, 🍐 = 2, 🍊 = 3. Расшифруем: 🍐 + 🍊 = 2 + 3 = 5.", "Кодирование — превращение сообщения в цифры и значки. Умение расшифровать — как ключ от сундука!"], "check": {"q": "Код: 🍎 = 1, 🍐 = 2, 🍊 = 3. Чему равно 🍐 + 🍊?", "choices": ["3", "5", "6", "4"], "ans": 1, "exp": "2 + 3 = 5."}, "tasks": [{"q": "Сколько чисел от 2 до 5 включительно?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Выпиши их: 2, 3, 4, 5.", "Их четыре."], "sol": "4"}, {"q": "Код: А = 1, Б = 2, В = 3. Какое число у буквы В?", "kind": "choice", "choices": ["1", "2", "3", "4"], "ans": 2, "tol": 0, "hints": ["А — 1, Б — 2…", "…В — 3."], "sol": "3"}]},
{"id": 311, "title": "Клетчатая бумага: подсчёты", "ico": "▦", "src": "Начальная школа · 1 класс · Олимп-1: клетки и фигуры", "subj": "jun", "explain": ["На клетчатой бумаге нарисован прямоугольник: 3 клетки в длину и 2 в высоту. Сколько всего клеток?", "Считаем рядами: 3 + 3 = 6. А можно столбиками: 2 + 2 + 2 = 6. Ответ одинаковый!", "Полоска из 5 клеток, закрасили через одну: получилось 3 закрашенные клетки.", "Удобно считать так: число клеток в ряду · число рядов."], "check": {"q": "Прямоугольник 2 на 3 клетки — сколько в нём клеток?", "choices": ["5", "6", "4", "9"], "ans": 1, "exp": "2 · 3 = 6 (или 3 + 3)."}, "tasks": [{"q": "Сколько клеток в полоске длиной 4 клетки и высотой 1?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Это просто 4 клетки подряд.", "4 · 1 = 4."], "sol": "4"}, {"q": "Фигура — две полоски по 3 клетки. Сколько клеток?", "kind": "choice", "choices": ["3", "5", "6", "9"], "ans": 2, "tol": 0, "hints": ["3 + 3.", "3 + 3 = 6 клеток."], "sol": "6"}]},
{"id": 312, "title": "Числа до 100: разряды", "ico": "🔢", "src": "Начальная школа · 2 класс · Нумерация чисел до 100", "subj": "jun", "explain": ["Числа до 100 состоят из десятков и единиц. В числе 57 — пять десятков и семь единиц.", "Запись: слева пишем десятки, справа единицы: 57 = 50 + 7.", "Сравниваем по разрядам: сначала десятки, потом единицы. 59 < 61, потому что 5 десятков < 6 десятков.", "Если десятков поровну, сравниваем единицы: 73 > 71."], "check": {"q": "Сколько десятков в числе 48?", "choices": ["4", "8", "48", "80"], "ans": 0, "exp": "48 = 4 десятка и 8 единиц."}, "tasks": [{"q": "Разложи на части: 73 = 70 + …?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["73 — 7 десятков и 3 единицы.", "70 + 3 = 73."], "sol": "3"}, {"q": "Что больше: 59 или 61?", "kind": "choice", "choices": ["59", "61", "они равны", "нельзя узнать"], "ans": 1, "tol": 0, "hints": ["Сравниваем десятки: 6 > 5.", "61 > 59."], "sol": "61"}]},
{"id": 313, "title": "Сложение и вычитание столбиком", "ico": "➕", "src": "Начальная школа · 2 класс · Письменные приёмы", "subj": "jun", "explain": ["Большие примеры считаем столбиком: единицы под единицами, десятки под десятками.", "34 + 25: единицы 4 + 5 = 9, десятки 3 + 2 = 5 → 59.", "36 + 27: 6 + 7 = 13 — пишем 3, а один десяток добавляем в следующий столбик: 3 + 2 + 1 = 6 → 63.", "Вычитание: 54 − 28. Из 4 нельзя вычесть 8 — занимаем десяток: 14 − 8 = 6; 5 − 1 − 2 = 2 → 26."], "check": {"q": "Найди 36 + 27", "choices": ["53", "63", "62", "73"], "ans": 1, "exp": "6 + 7 = 13 (пишем 3, десяток в уме); 3 + 2 + 1 = 6 → 63."}, "tasks": [{"q": "Чему равно 45 + 38?", "kind": "unit", "ans": 83, "tol": 0, "hints": ["5 + 8 = 13: единица 3, десяток в уме.", "4 + 3 + 1 = 8 → 83."], "sol": "83"}, {"q": "Чему равно 52 − 27?", "kind": "choice", "choices": ["25", "35", "31", "24"], "ans": 0, "tol": 0, "hints": ["Занимаем десяток: 12 − 7 = 5.", "5 − 1 − 2 = 2 → 25."], "sol": "25"}]},
{"id": 314, "title": "Умножение: смысл и таблица", "ico": "✖️", "src": "Начальная школа · 2 класс · Умножение и таблица", "subj": "jun", "explain": ["Умножение — сложение одинаковых слагаемых: 3 + 3 + 3 = 3 · 3 = 9. Читаем «3 по 3».", "Таблица умножения — все произведения от 1 · 1 до 9 · 9. Учим кусочками: сначала 2, потом 3, 4…", "2 · 4 = 8 — это «2 взять 4 раза»: 2 + 2 + 2 + 2 = 8.", "Секрет: от перестановки множителей произведение не меняется: 3 · 5 = 5 · 3 = 15."], "check": {"q": "Чему равно 3 · 4?", "choices": ["7", "12", "34", "9"], "ans": 1, "exp": "3 · 4 = 3 + 3 + 3 + 3 = 12."}, "tasks": [{"q": "Чему равно 4 · 3? (перестановка множителей)", "kind": "unit", "ans": 12, "tol": 0, "hints": ["4 · 3 — то же, что 3 · 4.", "3 · 4 = 12."], "sol": "12"}, {"q": "Сколько ножек у трёх стульев?", "kind": "choice", "choices": ["7", "12", "43", "9"], "ans": 1, "tol": 0, "hints": ["У стула 4 ножки.", "4 · 3 = 12."], "sol": "12"}]},
{"id": 315, "title": "Внетабличное умножение и деление", "ico": "➗", "src": "Начальная школа · 2 класс · Внетабличные случаи", "subj": "jun", "explain": ["Считаем примеры «за таблицей»: 12 · 3 = 12 + 12 + 12 = 36.", "Удобнее разложить: 12 = 10 + 2 → (10 + 2) · 3 = 30 + 6 = 36.", "Деление — обратное действие: 36 : 3 = 12, потому что 12 · 3 = 36.", "И при делении разбиваем на удобные части: 28 : 2 = (20 + 8) : 2 = 10 + 4 = 14."], "check": {"q": "Чему равно 12 · 4?", "choices": ["16", "48", "44", "84"], "ans": 1, "exp": "10 · 4 + 2 · 4 = 40 + 8 = 48."}, "tasks": [{"q": "Чему равно 28 : 2?", "kind": "unit", "ans": 14, "tol": 0, "hints": ["Разложи: 20 : 2 = 10, 8 : 2 = 4.", "10 + 4 = 14."], "sol": "14"}, {"q": "Чему равно 13 · 3?", "kind": "choice", "choices": ["16", "39", "36", "93"], "ans": 1, "tol": 0, "hints": ["13 = 10 + 3.", "10 · 3 + 3 · 3 = 30 + 9 = 39."], "sol": "39"}]},
{"id": 316, "title": "Деление с остатком", "ico": "🧮", "src": "Начальная школа · 2 класс · Деление с остатком", "subj": "jun", "explain": ["14 конфет раскладываем по 3 в пакетик. 14 : 3 = 4 пакетика, и 2 конфеты останутся.", "Остаток всегда МЕНЬШЕ делителя: берём самое большое число, кратное делителю, но не больше делимого: 3 · 4 = 12 ≤ 14.", "Остаток = делимое − делитель · частное: 14 − 12 = 2.", "Проверка: делитель · частное + остаток = делимое: 3 · 4 + 2 = 14 ✔."], "check": {"q": "Чему равен остаток при делении 17 на 5?", "choices": ["1", "2", "3", "4"], "ans": 1, "exp": "5 · 3 = 15; 17 − 15 = 2."}, "tasks": [{"q": "Найди остаток: 20 : 6", "kind": "unit", "ans": 2, "tol": 0, "hints": ["6 · 3 = 18.", "20 − 18 = 2."], "sol": "остаток 2"}, {"q": "19 : 4 = ?", "kind": "choice", "choices": ["4 и остаток 3", "4 и остаток 2", "5 и остаток 1", "3 и остаток 4"], "ans": 0, "tol": 0, "hints": ["4 · 4 = 16.", "19 − 16 = 3 → 4 и остаток 3."], "sol": "4 и 3"}]},
{"id": 317, "title": "Порядок действий: скобки", "ico": "🧮", "src": "Начальная школа · 2 класс · Порядок действий", "subj": "jun", "explain": ["В длинном примере договариваемся о порядке: сначала скобки, потом умножение и деление, затем сложение и вычитание.", "12 − (5 + 3): сначала в скобках 5 + 3 = 8, потом 12 − 8 = 4.", "Без скобок: 10 + 2 · 3 — сначала умножение: 2 · 3 = 6, потом 10 + 6 = 16 (а не 12 · 3!).", "Скобки меняют порядок: (10 + 2) · 3 = 12 · 3 = 36."], "check": {"q": "Чему равно (8 + 4) : 2?", "choices": ["6", "10", "4", "8"], "ans": 0, "exp": "8 + 4 = 12; 12 : 2 = 6."}, "tasks": [{"q": "Чему равно 7 + 2 · 5?", "kind": "unit", "ans": 17, "tol": 0, "hints": ["Сначала умножение: 2 · 5 = 10.", "7 + 10 = 17."], "sol": "17"}, {"q": "Чему равно 14 − (6 − 2)?", "kind": "choice", "choices": ["6", "10", "12", "8"], "ans": 1, "tol": 0, "hints": ["Сначала скобки: 6 − 2 = 4.", "14 − 4 = 10."], "sol": "10"}]},
{"id": 318, "title": "Распределительное свойство умножения", "ico": "🧩", "src": "Начальная школа · 2 класс · Свойства умножения", "subj": "jun", "explain": ["Распределительное свойство: умножаем каждое слагаемое отдельно: 3 · (10 + 4) = 3 · 10 + 3 · 4 = 30 + 12 = 42.", "Это помогает считать «неудобные» примеры: 3 · 14 = 3 · (10 + 4) = 42.", "Для вычитания тоже работает: 4 · (10 − 1) = 4 · 10 − 4 · 1 = 40 − 4 = 36.", "Буквами: a · (b + c) = a · b + a · c."], "check": {"q": "Чему равно 5 · (10 + 3)?", "choices": ["65", "53", "50", "58"], "ans": 0, "exp": "5 · 10 + 5 · 3 = 50 + 15 = 65."}, "tasks": [{"q": "Вычисли: 4 · 12 = 4 · (10 + 2) = …", "kind": "unit", "ans": 48, "tol": 0, "hints": ["4 · 10 = 40.", "4 · 2 = 8; 40 + 8 = 48."], "sol": "48"}, {"q": "Чему равно 3 · 19 = 3 · (20 − 1)?", "kind": "choice", "choices": ["57", "56", "53", "60"], "ans": 0, "tol": 0, "hints": ["3 · 20 = 60.", "60 − 3 · 1 = 60 − 3 = 57."], "sol": "57"}]},
{"id": 319, "title": "Сотни: числа до 1000", "ico": "🔟", "src": "Начальная школа · 2 класс · Нумерация до 1000", "subj": "jun", "explain": ["После 99 идёт 100 — одна сотня. В сотне 10 десятков.", "Числа до 1000: 245 — это 2 сотни, 4 десятка и 5 единиц.", "Записываем по разрядам: сотни, десятки, единицы: 340 = 3 сотни + 4 десятка.", "Сравниваем по сотням: 340 > 299, потому что 3 сотни > 2 сотни."], "check": {"q": "Сколько сотен в числе 632?", "choices": ["6", "3", "2", "63"], "ans": 0, "exp": "632 = 6 сотен, 3 десятка, 2 единицы."}, "tasks": [{"q": "Разложи: 500 + 40 + 7 = …?", "kind": "unit", "ans": 547, "tol": 0, "hints": ["5 сотен, 4 десятка, 7 единиц.", "500 + 40 + 7 = 547."], "sol": "547"}, {"q": "Что больше: 405 или 450?", "kind": "choice", "choices": ["405", "450", "они равны", "нельзя узнать"], "ans": 1, "tol": 0, "hints": ["Сотни равны (4 = 4).", "Сравниваем десятки: 0 < 5 → 450 больше."], "sol": "450"}]},
{"id": 320, "title": "Площадь: см², дм², м²", "ico": "▦", "src": "Начальная школа · 2 класс · Площадь фигур", "subj": "jun", "explain": ["Площадь — сколько места занимает фигура. Измеряем квадратами: квадрат 1 см × 1 см — это 1 квадратный сантиметр (см²).", "Площадь прямоугольника = длина · ширина в одинаковых единицах. Прямоугольник 4 см × 3 см: 4 · 3 = 12 см².", "Квадратный дециметр — квадрат 1 дм × 1 дм. В нём 100 квадратных сантиметров: 1 дм² = 100 см².", "Площадь квадрата = сторона · сторона: квадрат 3 см × 3 см имеет площадь 9 см²."], "check": {"q": "Чему равна площадь прямоугольника 5 см × 2 см?", "choices": ["7 см²", "10 см²", "52 см²", "14 см²"], "ans": 1, "exp": "5 · 2 = 10 см²."}, "tasks": [{"q": "Площадь квадрата со стороной 3 см?", "kind": "unit", "ans": 9, "tol": 0, "hints": ["У квадрата все стороны равны.", "3 · 3 = 9 см²."], "sol": "9 см²"}, {"q": "Сколько см² в квадрате 1 дм × 1 дм?", "kind": "choice", "choices": ["10", "100", "1000", "1"], "ans": 1, "tol": 0, "hints": ["1 дм = 10 см.", "10 · 10 = 100 см²."], "sol": "100 см²"}]},
{"id": 321, "title": "Объём: куб и параллелепипед", "ico": "📦", "src": "Начальная школа · 2 класс · Объём тел", "subj": "jun", "explain": ["Объём — сколько места внутри тела. Измеряем кубиками: кубик 1 см × 1 см × 1 см — 1 кубический сантиметр (см³).", "Коробка-параллелепипед 3 см × 2 см × 2 см: объём = 3 · 2 · 2 = 12 см³.", "Объём = длина · ширина · высота.", "Куб со стороной 2 см: 2 · 2 · 2 = 8 см³."], "check": {"q": "Чему равен объём куба со стороной 3 см?", "choices": ["9 см³", "27 см³", "6 см³", "12 см³"], "ans": 1, "exp": "3 · 3 · 3 = 27 см³."}, "tasks": [{"q": "Объём параллелепипеда 2 × 2 × 5 см?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["Перемножь три измерения.", "2 · 2 = 4; 4 · 5 = 20 см³."], "sol": "20 см³"}, {"q": "В чём измеряют вместимость жидкости в магазине?", "kind": "choice", "choices": ["в литрах", "в сантиметрах", "в граммах", "в минутах"], "ans": 0, "tol": 0, "hints": ["Литр — единица вместимости.", "Сок и молоко продают в литрах."], "sol": "в литрах"}]},
{"id": 322, "title": "Углы: прямой, острый, тупой", "ico": "📐", "src": "Начальная школа · 2 класс · Геометрия: углы", "subj": "jun", "explain": ["Угол — два луча из одной точки (вершины).", "Прямой угол — как угол тетради или буквы Л.", "Угол меньше прямого — острый (как остриё карандаша), больше прямого — тупой (как раскрытая книга).", "Проверяем угольником: приложили вершину — совпал с прямым углом? Если раскрыт меньше — острый, больше — тупой."], "check": {"q": "Какой угол меньше прямого?", "choices": ["острый", "тупой", "прямой", "развёрнутый"], "ans": 0, "exp": "Острый угол меньше прямого, тупой — больше."}, "tasks": [{"q": "Сколько прямых углов у прямоугольника?", "kind": "unit", "ans": 4, "tol": 0, "hints": ["Углы тетради — прямые.", "У прямоугольника их 4."], "sol": "4"}, {"q": "Какие углы у квадрата?", "kind": "choice", "choices": ["острые", "тупые", "прямые", "разные"], "ans": 2, "tol": 0, "hints": ["У квадрата все углы одинаковые.", "Все углы квадрата прямые."], "sol": "прямые"}]},
{"id": 323, "title": "Окружность: радиус и диаметр", "ico": "⭕", "src": "Начальная школа · 2 класс · Окружность", "subj": "jun", "explain": ["Окружность чертят циркулем. Точка в середине — центр.", "Радиус — отрезок от центра до окружности.", "Диаметр — отрезок через центр от края до края. Диаметр = два радиуса.", "Радиус 3 см → диаметр 6 см. Диаметр 8 см → радиус 4 см."], "check": {"q": "Диаметр окружности 10 см. Чему равен радиус?", "choices": ["5 см", "10 см", "20 см", "2 см"], "ans": 0, "exp": "Радиус — половина диаметра: 10 : 2 = 5 см."}, "tasks": [{"q": "Радиус 4 см — чему равен диаметр?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Диаметр — два радиуса.", "4 · 2 = 8 см."], "sol": "8 см"}, {"q": "Каким инструментом чертят окружность?", "kind": "choice", "choices": ["линейкой", "циркулем", "угольником", "транспортиром"], "ans": 1, "tol": 0, "hints": ["Циркуль держит иголку в центре.", "Окружность чертят циркулем."], "sol": "циркулем"}]},
{"id": 324, "title": "Задачи «на … и в … раз»", "ico": "🍎", "src": "Начальная школа · 2 класс · Задачи на сравнение", "subj": "jun", "explain": ["«На 3 больше» — прибавляем: 5 + 3. «В 3 раза больше» — умножаем: 5 · 3.", "«На 2 меньше» — вычитаем: 6 − 2. «В 2 раза меньше» — делим: 6 : 2.", "У Васи 6 яблок, у Пети в 2 раза больше: 6 · 2 = 12.", "У Кати на 2 яблока меньше, чем у Васи: 6 − 2 = 4. Слова «на» и «в» — разные действия!"], "check": {"q": "У Маши 4 конфеты, у Димы в 3 раза больше. Сколько конфет у Димы?", "choices": ["7", "12", "1", "34"], "ans": 1, "exp": "«В 3 раза больше» — умножаем: 4 · 3 = 12."}, "tasks": [{"q": "У Коли 10 марок, у Саши на 3 меньше. Сколько марок у Саши?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["«На 3 меньше» — вычитаем.", "10 − 3 = 7."], "sol": "7"}, {"q": "У Оли 8 наклеек, у Веры в 2 раза меньше. Сколько у Веры?", "kind": "choice", "choices": ["4", "6", "16", "10"], "ans": 0, "tol": 0, "hints": ["«В 2 раза меньше» — делим.", "8 : 2 = 4."], "sol": "4"}]},
{"id": 325, "title": "Буквенные выражения и формулы", "ico": "🔤", "src": "Начальная школа · 2 класс · Формулы периметра", "subj": "jun", "explain": ["Формула — короткая запись правила с буквами. Периметр прямоугольника: P = (a + b) · 2, где a и b — длины сторон.", "Прямоугольник 3 см и 5 см: P = (3 + 5) · 2 = 8 · 2 = 16 см.", "Меняем стороны — считаем заново: a = 4, b = 6 → P = (4 + 6) · 2 = 20 см.", "Периметр квадрата со стороной a: P = a · 4 (все стороны равны)."], "check": {"q": "Чему равен периметр прямоугольника 2 см и 4 см?", "choices": ["6 см", "8 см", "12 см", "24 см"], "ans": 2, "exp": "P = (2 + 4) · 2 = 6 · 2 = 12 см."}, "tasks": [{"q": "Периметр квадрата со стороной 5 см?", "kind": "unit", "ans": 20, "tol": 0, "hints": ["У квадрата 4 равные стороны.", "5 · 4 = 20 см."], "sol": "20 см"}, {"q": "Формула P = (a + b) · 2 — это периметр…", "kind": "choice", "choices": ["прямоугольника", "квадрата", "круга", "треугольника"], "ans": 0, "tol": 0, "hints": ["Складываем две разные стороны и удваиваем.", "Это периметр прямоугольника."], "sol": "прямоугольника"}]},
{"id": 326, "title": "Перебор и дерево вариантов", "ico": "🔀", "src": "Информатика · 5–6 класс · Олимп: перебор вариантов", "subj": "inf", "explain": ["Сколько двузначных чисел можно составить из цифр 1, 2 и 3, если цифры не повторяются? Выпишем: 12, 13, 21, 23, 31, 32 — всего 6.", "Такой способ — полный перебор: записываем все варианты и ничего не пропускаем.", "Удобнее рисовать дерево вариантов: первая цифра — 3 ветки, у каждой по 2 продолжения → 3 · 2 = 6.", "Правило умножения: если первый выбор имеет n вариантов, а второй — m, то всего n · m."], "check": {"q": "Сколько двузначных чисел можно составить из цифр 4, 5, 6, если цифры не повторяются?", "choices": ["6", "9", "3", "12"], "ans": 0, "exp": "Первая цифра — 3 варианта, вторая — 2: 3 · 2 = 6."}, "tasks": [{"q": "Сколько двузначных чисел можно составить из цифр 1, 2, 3, если цифры МОЖНО повторять?", "kind": "unit", "ans": 9, "tol": 0, "hints": ["Первая цифра — 3 варианта.", "Вторая — тоже 3: 3 · 3 = 9."], "sol": "3 · 3 = 9"}, {"q": "Сколько двузначных чисел можно составить из цифр 5 и 7 без повторов?", "kind": "choice", "choices": ["2", "4", "1", "3"], "ans": 0, "tol": 0, "hints": ["Выпиши их.", "57 и 75 — всего 2."], "sol": "57 и 75"}]},
{"id": 327, "title": "Оценка и пример", "ico": "⚖️", "src": "Информатика · 5–6 класс · Олимп: прикидка и оценка", "subj": "inf", "explain": ["Сумма 39 + 41 + 43. Не считая точно, оцени: больше или меньше 120? Заменим числа круглыми: примерно 40 + 40 + 40 = 120.", "Смотрим точнее: 41 и 43 больше 40, а 39 меньше — но «перевес» больше: 39 + 41 + 43 = 123 > 120.", "Такой приём — оценка: находим «вилку», внутри которой лежит ответ.", "На олимпиадах любят задачи «оцени, не считая» — тренируй замену чисел удобными круглыми!"], "check": {"q": "Не считая точно: 19 + 22 + 23 больше или меньше 60?", "choices": ["больше", "меньше", "ровно 60", "нельзя узнать"], "ans": 0, "exp": "Примерно 20+20+20=60, но 22 и 23 больше 20 → сумма больше 60 (это 64)."}, "tasks": [{"q": "Найди точную сумму: 10 + 11 + 12 + 13 + 14 (прикидка: среднее 12).", "kind": "unit", "ans": 60, "tol": 0, "hints": ["Среднее число здесь 12.", "12 · 5 = 60."], "sol": "10+11+12+13+14 = 60"}, {"q": "Оцени: 49 + 49 + 2 относительно 100.", "kind": "choice", "choices": ["больше 100", "меньше 100", "ровно 100", "нельзя узнать"], "ans": 2, "tol": 0, "hints": ["49 + 49 = 98.", "98 + 2 = 100 — ровно."], "sol": "ровно 100"}]},
{"id": 328, "title": "Быстрые прикидки и проверка ответа", "ico": "🔍", "src": "Информатика · 5–6 класс · Олимп: проверка решения", "subj": "inf", "explain": ["Как проверить вычисление, не пересчитывая всё заново? Посмотри на последнюю цифру: у 23 · 7 последняя цифра — как у 3 · 7 = 21, то есть 1.", "Проверяй обратным действием: если x + 7 = 15, то x = 15 − 7 = 8. Подставь: 8 + 7 = 15 ✔.", "Прикидка разрядов ловит ошибки: 18 · 3 не может быть 84 — ведь 20 · 3 = 60, значит ответ около 54.", "Всегда спрашивай себя: «похож ли ответ на правду?» — это ловит половину ошибок."], "check": {"q": "Проверь: 18 · 3 = 54.", "choices": ["да, верно", "нет, будет 48", "нет, будет 58", "нет, будет 44"], "ans": 0, "exp": "18 · 3 = 10·3 + 8·3 = 30 + 24 = 54 — верно."}, "tasks": [{"q": "Сумма трёх одинаковых чисел равна 27. Чему равно каждое число?", "kind": "unit", "ans": 9, "tol": 0, "hints": ["Делим сумму на 3.", "27 : 3 = 9."], "sol": "27 : 3 = 9"}, {"q": "Какая последняя цифра у произведения 23 · 7?", "kind": "choice", "choices": ["1", "6", "9", "3"], "ans": 0, "tol": 0, "hints": ["Достаточно 3 · 7.", "3 · 7 = 21 → последняя цифра 1 (23·7 = 161)."], "sol": "1"}]},
{"id": 329, "title": "Кодирование: олимпиадные задачи", "ico": "🔤", "src": "Информатика · 5–6 класс · Олимп: шифры и коды", "subj": "inf", "explain": ["Код-замена: каждой букве — её номер в алфавите: А = 1, Б = 2, …, Я = 33.", "Слово «КОТ»: К = 12, О = 16, Т = 20 → запись 12-16-20.", "Расшифруй 3-16-20: 3 = В, 16 = О, 20 = Т → получилось «ВОТ»!", "Кодирование — главная тема информатики: превращаем сообщение в числа и обратно."], "check": {"q": "Расшифруй 3-16-20 (А = 1, Б = 2, …).", "choices": ["ВОТ", "КОТ", "ГОТ", "ЛОТ"], "ans": 0, "exp": "3 = В, 16 = О, 20 = Т → «ВОТ»."}, "tasks": [{"q": "Под каким номером стоит буква К, если А = 1?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["А=1, Б=2, В=3…", "…К — двенадцатая буква."], "sol": "К = 12"}, {"q": "Слово зашифровано как 8-1-2-1 (А = 1). Что это за слово?", "kind": "choice", "choices": ["ЖАБА", "ИАБА", "ЗАБА", "ЖАВА"], "ans": 0, "tol": 0, "hints": ["8 = Ж, 1 = А, 2 = Б, 1 = А.", "8-1-2-1 → Ж-А-Б-А = «ЖАБА»."], "sol": "ЖАБА"}]},
{"id": 330, "title": "Графы-маршруты: поиск пути", "ico": "🕸️", "src": "Информатика · 5–6 класс · Олимп: графы и маршруты", "subj": "inf", "explain": ["Карта дорожек — это граф: городки (вершины) и дорожки между ними (рёбра).", "Нужен самый короткий путь. Ищем «слоями»: сначала городки на расстоянии 1 шага, потом 2.", "Пример: из А дорожки в Б и В. Из Б — в Д, из В — в Г и Д. До Д можно дойти за 2 шага: А→Б→Д или А→В→Д.", "Главное — не пропустить более короткий путь и не ходить по кругу."], "check": {"q": "Из А есть пути в Б и В; из Б — в Д; из В — в Д. Сколько шагов минимум от А до Д?", "choices": ["1", "2", "3", "4"], "ans": 1, "exp": "А→Б→Д или А→В→Д — оба пути по 2 шага."}, "tasks": [{"q": "Из пункта А выходит 3 дороги, из каждого следующего городка — по 2. Сколько городков на расстоянии 2 шага от А?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["На расстоянии 1 — 3 городка.", "Из каждого по 2: 3 · 2 = 6."], "sol": "3 · 2 = 6"}, {"q": "А соединено с Б и В; Б — с Г; В — с Г. Сколько разных путей из А в Г?", "kind": "choice", "choices": ["1", "2", "3", "4"], "ans": 1, "tol": 0, "hints": ["Перечисли маршруты.", "А→Б→Г и А→В→Г — два пути."], "sol": "2"}]},
{"id": 331, "title": "Алгоритмические головоломки: исполнитель", "ico": "🤖", "src": "Информатика · 5–6 класс · Олимп: исполнители", "subj": "inf", "explain": ["Робот-исполнитель выполняет команды: шаг, поворот вправо, поворот влево.", "Робот смотрел на север и выполнил: вправо, шаг, влево. После «вправо» он смотрит на восток, после «влево» — снова на север!", "Считаем сдвиг по шагам: каждый «шаг» двигает робота туда, куда он сейчас смотрит.", "Следи за двумя вещами: куда смотрит робот и где он находится."], "check": {"q": "Робот смотрел на север. Команды: вправо, шаг, влево. Куда он смотрит?", "choices": ["на север", "на юг", "на запад", "на восток"], "ans": 0, "exp": "Вправо от севера — восток; влево от востока — снова север."}, "tasks": [{"q": "Команды: шаг, шаг, назад, шаг. На сколько шагов робот продвинулся вперёд?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Шаг = +1, назад = −1.", "+1 +1 −1 +1 = +2."], "sol": "на 2 шага"}, {"q": "Робот стартовал в клетке (1,1) и смотрел вверх. Команды: шаг, шаг, поворот вправо, шаг. В какой он клетке?", "kind": "choice", "choices": ["(2,3)", "(3,2)", "(1,4)", "(2,1)"], "ans": 0, "tol": 0, "hints": ["Вверх — растёт вторая координата.", "(1,1)→(1,2)→(1,3)→поворот вправо→шаг вправо→(2,3)."], "sol": "(2,3)"}]},
{"id": 332, "title": "Игры-стратегии", "ico": "🎮", "src": "Информатика · 5–6 класс · Олимп: выигрышные стратегии", "subj": "inf", "explain": ["Игры «забери последнюю фишку»: за ход берут 1 или 2 фишки, кто не может сходить — проиграл.", "Если фишек 8 и берут по одной — ходов ровно 8: последний (8-й) ход делает второй → выигрывает второй.", "Если фишек 7 — последний ход у первого: выигрывает первый.", "Правило: при игре «по одной» чётное число фишек выгодно второму, нечётное — первому."], "check": {"q": "На столе 8 фишек, за ход берут ровно 1, кто не может сходить — проиграл. Кто выиграет?", "choices": ["первый", "второй", "ничья", "нельзя узнать"], "ans": 1, "exp": "Ходов 8 — чётно, последний (8-й) ход делает второй."}, "tasks": [{"q": "Полоска из 7 клеток: красят по одной клетке, кто не может сходить — проиграл. Кто выигрывает?", "kind": "choice", "choices": ["первый", "второй"], "ans": 0, "tol": 0, "hints": ["7 — нечётное число клеток.", "Первый красит 7-ю (последнюю) клетку и выигрывает."], "sol": "первый"}, {"q": "На столе 6 конфет, за ход берут 1 или 2, кто не может сходить — проиграл. Кто выиграет при правильной игре?", "kind": "choice", "choices": ["первый", "второй"], "ans": 1, "tol": 0, "hints": ["Приём «дополняй до 3».", "6 делится на 3: второй дополняет ход первого до 3 и забирает последнюю конфету."], "sol": "второй"}]},
{"id": 333, "title": "Таблицы и схемы в задачах", "ico": "📊", "src": "Информатика · 5–6 класс · Олимп: таблицы", "subj": "inf", "explain": ["В таблице отметок строки — ученики, столбцы — предметы, галочка ✔ означает «пятёрка».", "У Пети ✔ в математике и рисовании (2), у Васи — только в чтении (1), у Тани — во всех трёх (3).", "Чтобы ответить «у кого больше всех пятёрок», сосчитай галочки в каждой строке.", "Таблицы помогают не запутаться: одна клетка = один факт."], "check": {"q": "У Пети ✔ в математике и рисовании, у Васи — в чтении, у Тани — во всех трёх. У кого больше всего ✔?", "choices": ["у Пети", "у Васи", "у Тани", "поровну"], "ans": 2, "exp": "Таня — 3 галочки, Петя — 2, Вася — 1."}, "tasks": [{"q": "Сколько ✔ у Пети, если у него пятёрки по математике и рисованию?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Посчитай галочки в строке Пети.", "Математика + рисование = 2."], "sol": "2"}, {"q": "В таблице 4 строки и 3 столбца. Сколько всего клеток?", "kind": "choice", "choices": ["7", "12", "4", "3"], "ans": 1, "tol": 0, "hints": ["Умножь строки на столбцы.", "4 · 3 = 12 клеток."], "sol": "12"}]},
{"id": 334, "title": "Закономерности и последовательности", "ico": "🔢", "src": "Информатика · 5–6 класс · Олимп: числовые ряды", "subj": "inf", "explain": ["Ряд 1, 2, 4, 7, 11, … растёт всё быстрее: разности 1, 2, 3, 4 — каждая следующая на 1 больше.", "Следующая разность 5: 11 + 5 = 16.", "Бывают ряды с умножением: 3, 6, 12, 24 — каждое число вдвое больше предыдущего.", "Сначала найди закон (сложение, вычитание, умножение или смешанное), потом продолжай."], "check": {"q": "Продолжи ряд: 1, 2, 4, 7, 11, …", "choices": ["15", "16", "14", "13"], "ans": 1, "exp": "Разности +1, +2, +3, +4 → следующая +5: 16."}, "tasks": [{"q": "Продолжи ряд: 3, 6, 12, 24, …", "kind": "unit", "ans": 48, "tol": 0, "hints": ["Каждое число удваивается.", "24 · 2 = 48."], "sol": "48"}, {"q": "Какое число лишнее: 4, 9, 16, 25, 33?", "kind": "choice", "choices": ["4", "16", "33", "25"], "ans": 2, "tol": 0, "hints": ["Это квадраты чисел.", "4=2², 9=3², 16=4², 25=5² — лишнее 33."], "sol": "33"}]},
{"id": 335, "title": "Шифры и секретные коды: финал", "ico": "🗝️", "src": "Информатика · 5–6 класс · Олимп: сложные шифры", "subj": "inf", "explain": ["Сложный шифр — несколько шагов сразу. Пример: каждую цифру заменили следующей (0→1, 1→2, …, 9→0).", "Получили 789. Расшифровываем, сдвигая каждую цифру на одну назад: 7→6, 8→7, 9→8 → было число 678.", "Другой шифр — перестановка: 123 записали наоборот — 321.", "Расшифровывая, применяй обратные шаги в обратном порядке!"], "check": {"q": "Каждую цифру заменили следующей (0→1, …, 9→0). Получили 789. Какое было число?", "choices": ["678", "890", "879", "698"], "ans": 0, "exp": "Сдвигаем назад: 7→6, 8→7, 9→8 → 678."}, "tasks": [{"q": "Цифры числа переставили наоборот: 12 → 21. Что получится из числа 21?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Просто переставь цифры.", "21 → 12."], "sol": "12"}, {"q": "Шифр-зеркало: 123 → 321. Что станет с числом 246?", "kind": "choice", "choices": ["642", "462", "624", "264"], "ans": 0, "tol": 0, "hints": ["Читаем справа налево.", "246 → 642."], "sol": "642"}]},
{"id": 336, "title": "Чётность: чёт и нечет", "ico": "🔀", "src": "Начальная школа · 2 класс · Олимп-2: чётность", "subj": "jun", "explain": ["Чётные числа делятся на 2: 0, 2, 4, 6, 8… Нечётные — не делятся: 1, 3, 5, 7, 9…", "Правила сложения: чёт + чёт = чёт, нечёт + нечёт = чёт, а чёт + нечёт = нечёт.", "Пример: можно ли разложить 9 конфет на две равные кучки? 9 — нечётное, нельзя. А 10 — можно: 5 и 5.", "Секрет: сумма двух одинаковых чисел всегда чётная!"], "check": {"q": "Какая сумма: 7 + 8?", "choices": ["чётная", "нечётная", "ни то ни сё", "зависит от чисел"], "ans": 1, "exp": "7 — нечёт, 8 — чёт: чёт + нечёт = нечёт (7+8 = 15)."}, "tasks": [{"q": "Сколько чётных чисел от 1 до 10?", "kind": "unit", "ans": 5, "tol": 0, "hints": ["Выпиши: 2, 4, 6, 8, 10.", "Их пять."], "sol": "5"}, {"q": "Можно ли 12 конфет разложить на две равные кучки?", "kind": "choice", "choices": ["да, по 6", "да, по 5 и 7", "нет", "да, по 7 и 5"], "ans": 0, "tol": 0, "hints": ["12 — чётное число.", "12 : 2 = 6 — да, по 6 конфет."], "sol": "да, по 6"}]},
{"id": 337, "title": "Инварианты: что не меняется", "ico": "🧊", "src": "Начальная школа · 2 класс · Олимп-2: инварианты", "subj": "jun", "explain": ["Инвариант — то, что НЕ меняется при любых разрешённых действиях.", "Переставили слагаемые местами — сумма не изменилась: 3 + 5 = 5 + 3 = 8.", "Игра: числа 2, 4, 6. Разрешается менять местами любые два числа. Сумма 2+4+6 = 12 и останется 12 — сумма инвариант.", "Если сумма чисел нечётная, а действие «менять местами» её не меняет — противоречия быть не может."], "check": {"q": "Числа 3, 5, 7 меняют местами. Что точно НЕ изменится?", "choices": ["сумма", "самое большое место", "порядок", "ничего"], "ans": 0, "exp": "От перестановки слагаемых сумма не меняется: 3+5+7 = 15 всегда."}, "tasks": [{"q": "Чему равна сумма 4 + 6 + 8 после любой перестановки?", "kind": "unit", "ans": 18, "tol": 0, "hints": ["Сложи сначала.", "4+6+8 = 18 — и останется 18."], "sol": "18"}, {"q": "Сумма трёх чисел равна 20. Одно число увеличили на 3. Что сделать со вторым, чтобы сумма не изменилась?", "kind": "choice", "choices": ["уменьшить на 3", "увеличить на 3", "не трогать", "уменьшить на 6"], "ans": 0, "tol": 0, "hints": ["Сумма — инвариант.", "+3 и −3 компенсируются: сумма остаётся 20."], "sol": "уменьшить на 3"}]},
{"id": 338, "title": "Принцип Дирихле: кролики и клетки", "ico": "🕊️", "src": "Начальная школа · 2 класс · Олимп-2: Дирихле", "subj": "jun", "explain": ["Если 3 кролика посадить в 2 клетки, то в какой-то клетке окажется НЕ меньше 2 кроликов.", "Это принцип Дирихле: если кроликов больше, чем клеток, найдётся клетка минимум с двумя.", "9 шаров раскладываем в 3 коробки — если поровну, по 3; если не поровну, где-то больше 3.", "Правило: «больше предметов, чем мест → есть место с несколькими»."], "check": {"q": "5 кроликов и 4 клетки. Верно ли, что в какой-то клетке не меньше 2 кроликов?", "choices": ["да", "нет", "нельзя узнать", "только если кроликов 6"], "ans": 0, "exp": "Кроликов больше, чем клеток → по Дирихле есть клетка минимум с 2."}, "tasks": [{"q": "7 яблок разложили в 6 корзин. Сколько яблок минимум в какой-то корзине?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Предметов больше, чем мест.", "Хотя бы в одной корзине не меньше 2 яблок."], "sol": "2"}, {"q": "Сколько нужно кроликов, чтобы гарантированно найти клетку с двумя, если клеток 3?", "kind": "choice", "choices": ["4", "3", "2", "6"], "ans": 0, "tol": 0, "hints": ["Кроликов должно быть больше клеток.", "3 + 1 = 4 кролика."], "sol": "4"}]},
{"id": 339, "title": "Раскраски: шахматная доска", "ico": "♟️", "src": "Начальная школа · 2 класс · Олимп-2: раскраски", "subj": "jun", "explain": ["Шахматная доска раскрашена в шахматном порядке: белые и чёрные клетки чередуются.", "Домино (прямоугольник 1×2) всегда накрывает ОДНУ белую и ОДНУ чёрную клетку.", "Значит, если белых клеток больше, чем чёрных, домино не сможет покрыть всю доску!", "Так раскраска помогает доказать «невозможность»."], "check": {"q": "Полоска из 5 клеток раскрашена в шахматном порядке: Б Ч Б Ч Б. Можно ли покрыть её целиком домино 1×2?", "choices": ["нет", "да", "можно, если перевернуть", "нельзя узнать"], "ans": 0, "exp": "Белых 3, чёрных 2 — домино накрывает поровну, значит нельзя."}, "tasks": [{"q": "Сколько чёрных клеток в полоске Б Ч Б Ч Б?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Посчитай.", "Чёрные — 2-я и 4-я: две."], "sol": "2"}, {"q": "Сколько белых клеток у полоски 1×4, если она начинается с белой?", "kind": "choice", "choices": ["2", "3", "1", "4"], "ans": 0, "tol": 0, "hints": ["Б Ч Б Ч.", "Белых две."], "sol": "2"}]},
{"id": 340, "title": "Взвешивания и переливания", "ico": "⚖️", "src": "Начальная школа · 2 класс · Олимп-2: взвешивания", "subj": "jun", "explain": ["Три монеты, одна легче других, остальные одинаковые. Как найти лёгкую за ОДНО взвешивание на чашечных весах?", "Кладём по одной монете на чаши. Если весы в равновесии — лёгкая та, что осталась. Если нет — лёгкая выше!", "Переливания: есть бидон 5 л и банка 3 л. Как отмерить 2 л? Наполним 5 л, отольём 3 л в банку — останется 2 л.", "Секрет переливаний: ищем разность объёмов."], "check": {"q": "Три монеты, одна лёгкая. Взвесили монеты 1 и 2 — весы в равновесии. Какая монета лёгкая?", "choices": ["монета 3", "монета 1", "монета 2", "нельзя узнать"], "ans": 0, "exp": "Раз 1 и 2 равны, лёгкая — оставшаяся, монета 3."}, "tasks": [{"q": "Бидон 5 л наполнили и отлили 3 л в банку. Сколько литров осталось в бидоне?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["5 − 3.", "5 − 3 = 2 л."], "sol": "2 л"}, {"q": "Есть полный бидон 5 л и пустая банка 3 л. Можно ли отмерить ровно 2 л?", "kind": "choice", "choices": ["да: отлить 3 л", "нет", "да: наполнить банку дважды", "нельзя узнать"], "ans": 0, "tol": 0, "hints": ["5 − 3 = 2.", "Отлить из 5 л в банку 3 л — в бидоне останется 2 л."], "sol": "да"}]},
{"id": 341, "title": "Игры: выигрышная стратегия", "ico": "🎮", "src": "Начальная школа · 2 класс · Олимп-2: игры", "subj": "jun", "explain": ["Две одинаковые кучки по 2 конфеты. За ход берут из ЛЮБОЙ кучки сколько угодно (но не из двух сразу). Кто взял последнюю конфету — выиграл.", "Стратегия второго — КОПИРОВАНИЕ: что бы первый ни сделал в одной кучке, второй повторяет в другой.", "Первый взял 1 конфету из левой кучки → второй берёт 1 из правой. Кучки снова равны!", "Когда кучки равны, второй всегда отвечает симметрично и забирает последнюю конфету → выигрывает второй."], "check": {"q": "Две кучки по 2 конфеты, за ход берут из одной кучки сколько угодно. Кто выигрывает при правильной игре?", "choices": ["первый", "второй", "ничья", "нельзя узнать"], "ans": 1, "exp": "Второй копирует ход в другой кучке и выигрывает."}, "tasks": [{"q": "Первый взял 1 конфету из левой кучки. Сколько должен взять второй из правой, чтобы кучки снова сравнялись?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Стратегия — копирование.", "Взять 1: в обеих кучках по 1."], "sol": "1"}, {"q": "Кучки по 1 конфете, ход — первый. Кто возьмёт последнюю конфету?", "kind": "choice", "choices": ["первый", "второй", "никто", "оба"], "ans": 0, "tol": 0, "hints": ["Ход всего один.", "Первый берёт 1 конфету и выигрывает."], "sol": "первый"}]},
{"id": 342, "title": "Движение: скорость и время", "ico": "🚴", "src": "Начальная школа · 2 класс · Олимп-2: движение", "subj": "jun", "explain": ["Пешеход идёт со скоростью 4 км/ч — значит, за каждый час проходит 4 км.", "За 2 часа он пройдёт 4 · 2 = 8 км. За 3 часа — 4 · 3 = 12 км.", "Формула: путь = скорость · время.", "Обратная задача: прошёл 15 км за 3 часа → скорость 15 : 3 = 5 км/ч."], "check": {"q": "Велосипедист едет со скоростью 6 км/ч. Сколько километров он проедет за 2 часа?", "choices": ["12 км", "8 км", "3 км", "10 км"], "ans": 0, "exp": "Путь = скорость · время: 6 · 2 = 12 км."}, "tasks": [{"q": "Пешеход идёт 4 км/ч. Сколько км он пройдёт за 3 часа?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["4 км за час.", "4 · 3 = 12 км."], "sol": "12 км"}, {"q": "За 2 часа проехали 10 км. Какая была скорость?", "kind": "choice", "choices": ["5 км/ч", "20 км/ч", "8 км/ч", "10 км/ч"], "ans": 0, "tol": 0, "hints": ["Скорость = путь : время.", "10 : 2 = 5 км/ч."], "sol": "5 км/ч"}]},
{"id": 343, "title": "Многозначные числа: разряды и классы", "ico": "🔢", "src": "Начальная школа · 3 класс · Числа до миллиона", "subj": "jun", "explain": ["Числа до миллиона записывают по классам: класс единиц (единицы, десятки, сотни) и класс тысяч.", "5348 = 5 тысяч + 3 сотни + 4 десятка + 8 единиц. Читаем: пять тысяч триста сорок восемь.", "В числе 45 000 — сорок пять тысяч: цифры 4 и 5 показывают тысячи, дальше нули.", "Разряды считаем справа налево: единицы, десятки, сотни, единицы тысяч, десятки тысяч, сотни тысяч."], "check": {"q": "Сколько тысяч в числе 45 000?", "choices": ["45", "4", "5", "4500"], "ans": 0, "exp": "45 000 = 45 тысяч."}, "tasks": [{"q": "Запиши цифрами: три тысячи четыреста двадцать", "kind": "unit", "ans": 3420, "tol": 0, "hints": ["Три тысячи — 3, четыреста — 4…", "3 тысячи 4 сотни 2 десятка = 3420."], "sol": "3420"}, {"q": "Что больше: 999 или 1000?", "kind": "choice", "choices": ["999", "1000", "они равны", "нельзя узнать"], "ans": 1, "tol": 0, "hints": ["После 999 идёт 1000.", "1000 > 999."], "sol": "1000"}]},
{"id": 344, "title": "Умножение и деление на 10, 100, 1000", "ico": "✨", "src": "Начальная школа · 3 класс · Действия с круглыми числами", "subj": "jun", "explain": ["При умножении на 10 приписываем один ноль: 47 · 10 = 470.", "При умножении на 100 приписываем два нуля: 47 · 100 = 4700; на 1000 — три нуля.", "Деление — наоборот, убираем нули: 4700 : 100 = 47; 6000 : 1000 = 6.", "Секрет: считай, сколько нулей у множителя, и приписывай столько же."], "check": {"q": "Чему равно 63 · 100?", "choices": ["630", "6300", "603", "63000"], "ans": 1, "exp": "Приписываем два нуля: 6300."}, "tasks": [{"q": "Чему равно 5200 : 100?", "kind": "unit", "ans": 52, "tol": 0, "hints": ["Убираем два нуля.", "5200 : 100 = 52."], "sol": "52"}, {"q": "Чему равно 8 · 1000?", "kind": "choice", "choices": ["800", "8000", "80", "80000"], "ans": 1, "tol": 0, "hints": ["Три нуля.", "8 · 1000 = 8000."], "sol": "8000"}]},
{"id": 345, "title": "Письменное умножение и деление", "ico": "✖️", "src": "Начальная школа · 3 класс · Письменные вычисления", "subj": "jun", "explain": ["Умножаем по разрядам: 234 · 2. Сначала единицы 4 · 2 = 8, потом десятки 3 · 2 = 6, сотни 2 · 2 = 4 → 468.", "Удобно: 234 · 2 = (200 + 30 + 4) · 2 = 400 + 60 + 8 = 468.", "Деление: 96 : 3. Делим десятки: 9 : 3 = 3, единицы 6 : 3 = 2 → 32.", "Всегда проверяй умножением: 32 · 3 = 96 ✔."], "check": {"q": "Чему равно 123 · 3?", "choices": ["369", "363", "366", "396"], "ans": 0, "exp": "100·3 + 20·3 + 3·3 = 300 + 60 + 9 = 369."}, "tasks": [{"q": "Чему равно 84 : 4?", "kind": "unit", "ans": 21, "tol": 0, "hints": ["80 : 4 = 20.", "4 : 4 = 1 → 20 + 1 = 21."], "sol": "84 : 4 = 21"}, {"q": "Чему равно 312 · 2?", "kind": "choice", "choices": ["624", "614", "634", "326"], "ans": 0, "tol": 0, "hints": ["300·2 = 600, 12·2 = 24.", "600 + 24 = 624."], "sol": "624"}]},
{"id": 346, "title": "Величины: масса, время, деньги", "ico": "⚖️", "src": "Начальная школа · 3 класс · Единицы величин", "subj": "jun", "explain": ["Масса: 1 кг = 1000 г, 1 ц = 100 кг, 1 т = 10 ц = 1000 кг.", "Время: 1 ч = 60 мин, 1 мин = 60 с. Деньги: 1 рубль = 100 копеек.", "Переводим в меньшие единицы умножением: 2 кг = 2000 г; 3 ч = 180 мин.", "Сравнивать можно только одинаковые единицы!"], "check": {"q": "Сколько граммов в 1 кг?", "choices": ["100", "1000", "10", "10000"], "ans": 1, "exp": "1 кг = 1000 г."}, "tasks": [{"q": "Сколько минут в 2 часах?", "kind": "unit", "ans": 120, "tol": 0, "hints": ["1 ч = 60 мин.", "2 · 60 = 120 мин."], "sol": "120 мин"}, {"q": "Что больше: 1 кг или 500 г?", "kind": "choice", "choices": ["1 кг", "500 г", "они равны", "нельзя сравнить"], "ans": 0, "tol": 0, "hints": ["1 кг = 1000 г.", "1000 г > 500 г."], "sol": "1 кг"}]},
{"id": 347, "title": "Формула пути: s = v · t", "ico": "🚗", "src": "Начальная школа · 3 класс · Формулы: путь", "subj": "jun", "explain": ["Скорость показывает, сколько километров проходит объект за 1 час.", "Пешеход идёт 5 км/ч и идёт 3 часа: путь s = 5 · 3 = 15 км.", "Формула пути: s = v · t. Из неё: v = s : t и t = s : v.", "За 4 часа поезд прошёл 240 км → скорость v = 240 : 4 = 60 км/ч."], "check": {"q": "Скорость 6 км/ч, время 2 ч. Какой путь?", "choices": ["12 км", "8 км", "3 км", "10 км"], "ans": 0, "exp": "s = 6 · 2 = 12 км."}, "tasks": [{"q": "За 4 часа поезд прошёл 240 км. Какая скорость?", "kind": "unit", "ans": 60, "tol": 0, "hints": ["Скорость = путь : время.", "240 : 4 = 60 км/ч."], "sol": "60 км/ч"}, {"q": "Скорость 8 км/ч, путь 24 км. Сколько времени?", "kind": "choice", "choices": ["3 ч", "4 ч", "2 ч", "6 ч"], "ans": 0, "tol": 0, "hints": ["t = s : v.", "24 : 8 = 3 ч."], "sol": "3 ч"}]},
{"id": 348, "title": "Формула стоимости: a = b · c", "ico": "🛒", "src": "Начальная школа · 3 класс · Формулы: цена, количество, стоимость", "subj": "jun", "explain": ["Булочка стоит 7 рублей (цена), купили 4 штуки (количество). Стоимость = 7 · 4 = 28 рублей.", "Формула: стоимость = цена · количество (a = b · c).", "Ищем цену: цена = стоимость : количество. 48 рублей за 6 тетрадей → 48 : 6 = 8 рублей.", "Ищем количество: количество = стоимость : цена."], "check": {"q": "Цена 9 рублей, купили 5 штук. Какая стоимость?", "choices": ["45 руб.", "14 руб.", "40 руб.", "54 руб."], "ans": 0, "exp": "9 · 5 = 45 руб."}, "tasks": [{"q": "За 6 тетрадей заплатили 48 руб. Цена одной тетради?", "kind": "unit", "ans": 8, "tol": 0, "hints": ["Цена = стоимость : количество.", "48 : 6 = 8 руб."], "sol": "8 руб."}, {"q": "Карандаш стоит 6 руб. Сколько карандашей можно купить на 30 руб.?", "kind": "choice", "choices": ["5", "6", "4", "24"], "ans": 0, "tol": 0, "hints": ["Количество = стоимость : цена.", "30 : 6 = 5 карандашей."], "sol": "5"}]},
{"id": 349, "title": "Уравнения: составные", "ico": "⚖️", "src": "Начальная школа · 3 класс · Уравнения с несколькими действиями", "subj": "jun", "explain": ["Составное уравнение решаем по шагам: сначала находим выражение со скобками.", "(x + 3) · 2 = 16 → сначала x + 3 = 16 : 2 = 8, потом x = 8 − 3 = 5.", "Проверка: (5 + 3) · 2 = 8 · 2 = 16 ✔.", "Помни связки: «найди часть — вычитанием, найди целое — сложением, найди множитель — делением»."], "check": {"q": "Реши: x · 3 = 21", "choices": ["7", "6", "18", "24"], "ans": 0, "exp": "x — множитель: 21 : 3 = 7."}, "tasks": [{"q": "Реши: x : 5 = 6", "kind": "unit", "ans": 30, "tol": 0, "hints": ["x — делимое.", "x = 6 · 5 = 30."], "sol": "30"}, {"q": "Реши: 4 · x = 36", "kind": "choice", "choices": ["9", "8", "40", "32"], "ans": 0, "tol": 0, "hints": ["x — множитель.", "36 : 4 = 9."], "sol": "9"}]},
{"id": 350, "title": "Неравенства", "ico": "📊", "src": "Начальная школа · 3 класс · Сравнение выражений", "subj": "jun", "explain": ["Знаки сравнения: > (больше), < (меньше), = (равно).", "Сравниваем выражения, считая обе части: 6 · 7 = 42, а 5 · 8 = 40 → 42 > 40.", "Двойное неравенство 3 < x < 7: x больше 3 и меньше 7. Целые решения: 4, 5, 6.", "Иногда выражения сравнивают умно, не считая всё: 250 : 5 = 50 < 60."], "check": {"q": "Что больше: 6 · 7 или 5 · 8?", "choices": ["6 · 7", "5 · 8", "они равны", "нельзя узнать"], "ans": 0, "exp": "42 > 40."}, "tasks": [{"q": "Сколько целых чисел подходит: 3 < x < 7?", "kind": "unit", "ans": 3, "tol": 0, "hints": ["Выпиши их.", "4, 5, 6 — три числа."], "sol": "3"}, {"q": "Верно ли, что 250 : 5 < 60?", "kind": "choice", "choices": ["да", "нет", "они равны", "нельзя узнать"], "ans": 0, "tol": 0, "hints": ["250 : 5 = 50.", "50 < 60 — верно."], "sol": "да"}]},
{"id": 351, "title": "Множества и диаграммы Эйлера–Венна", "ico": "🧩", "src": "Начальная школа · 3 класс · Множества", "subj": "jun", "explain": ["Множество — набор предметов: {1, 2, 3, 4} — множество чисел.", "Пересечение множеств — общие элементы: А = {1,2,3,4} и В = {3,4,5} пересекаются в {3,4}.", "Круги Эйлера–Венна рисуют два множества; серединка (пересечение) — то, что в обоих.", "В классе 10 ребят любят математику, 7 — рисование, 3 — и то и другое. Только математику любят 10 − 3 = 7."], "check": {"q": "А = {1,2,3,4}, В = {3,4,5}. Что в пересечении?", "choices": ["{3,4}", "{1,2}", "{5}", "пусто"], "ans": 0, "exp": "Общие элементы — 3 и 4."}, "tasks": [{"q": "Сколько элементов в пересечении А = {2,4,6} и В = {1,2,3,4}?", "kind": "unit", "ans": 2, "tol": 0, "hints": ["Общие: 2 и 4.", "Два элемента."], "sol": "2"}, {"q": "10 ребят любят математику, 7 — рисование, 3 — и то и другое. Сколько любят ТОЛЬКО математику?", "kind": "choice", "choices": ["7", "10", "3", "13"], "ans": 0, "tol": 0, "hints": ["Вычти тех, кто любит и то и другое.", "10 − 3 = 7."], "sol": "7"}]},
{"id": 352, "title": "Высказывания: и, или, не", "ico": "🧠", "src": "Начальная школа · 3 класс · Логика высказываний", "subj": "jun", "explain": ["Высказывание — предложение, про которое можно сказать: истина или ложь.", "«И» — оба условия верны. «ИЛИ» — верно хотя бы одно. «НЕ» — отрицание.", "«Число 12 чётное И делится на 3» — истина: 12 чётное и 12 : 3 = 4.", "«Число 9 НЕ делится на 3» — ложь, потому что 9 : 3 = 3."], "check": {"q": "Высказывание «12 чётное И делится на 3» — истина или ложь?", "choices": ["истина", "ложь", "нельзя узнать", "это не высказывание"], "ans": 0, "exp": "12 чётное и 12 : 3 = 4 — оба верно → истина."}, "tasks": [{"q": "«Число 9 НЕ делится на 3» — истина или ложь?", "kind": "choice", "choices": ["истина", "ложь"], "ans": 1, "tol": 0, "hints": ["9 : 3 = 3.", "9 делится на 3, значит «НЕ делится» — ложь."], "sol": "ложь"}, {"q": "«5 > 3 ИЛИ 5 < 1» — истина или ложь?", "kind": "choice", "choices": ["истина", "ложь"], "ans": 0, "tol": 0, "hints": ["Для «ИЛИ» достаточно одного верного.", "5 > 3 верно → истина."], "sol": "истина"}]},
{"id": 353, "title": "Симметрия и развёртки", "ico": "🦋", "src": "Начальная школа · 3 класс · Симметрия", "subj": "jun", "explain": ["Осевая симметрия — отражение относительно прямой: левая половина как зеркало правой.", "Симметричные фигуры: квадрат, круг, бабочка. Буквы А, М, Т, О симметричны.", "У квадрата 4 оси симметрии: две через середины сторон и две диагонали.", "Развёртка куба — 6 квадратов, из которых можно сложить куб."], "check": {"q": "Сколько осей симметрии у квадрата?", "choices": ["2", "4", "1", "0"], "ans": 1, "exp": "Две через середины сторон и две диагонали — всего 4."}, "tasks": [{"q": "Сколько граней у куба?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Куб похож на игральный кубик.", "У куба 6 граней."], "sol": "6"}, {"q": "Какая буква симметрична относительно вертикальной оси?", "kind": "choice", "choices": ["А", "Б", "Г", "Р"], "ans": 0, "tol": 0, "hints": ["Сложи букву пополам мысленно.", "У А левая и правая части совпадают."], "sol": "А"}]},
{"id": 354, "title": "Перебор и оценка: олимпиадные задачи", "ico": "🔍", "src": "Начальная школа · 3 класс · Олимп-3: перебор", "subj": "jun", "explain": ["Число больше 30 и меньше 40, сумма цифр равна 7. Перебираем 31…39: у 34 сумма 3 + 4 = 7 → ответ 34.", "Перебор — проверяем все варианты по порядку; удобно сужать рамки условиями.", "Оценка: сумма 38 + 39 + 40. Заменим на 40 · 3 = 120, но 38 и 39 меньше 40: точный ответ 117.", "Сначала оцени (примерно), потом посчитай точно и сравни."], "check": {"q": "Число больше 30 и меньше 40, сумма цифр равна 7. Какое это число?", "choices": ["34", "35", "36", "37"], "ans": 0, "exp": "3 + 4 = 7 — подходит 34."}, "tasks": [{"q": "Найди точную сумму: 38 + 39 + 40", "kind": "unit", "ans": 117, "tol": 0, "hints": ["39 · 3 = 117 (или 40·3 − 3).", "38+39+40 = 117."], "sol": "117"}, {"q": "Число от 10 до 20, делится и на 3, и на 4. Какое?", "kind": "choice", "choices": ["12", "16", "18", "20"], "ans": 0, "tol": 0, "hints": ["Ищем общее кратное.", "12 : 3 = 4 и 12 : 4 = 3 → 12."], "sol": "12"}]},
{"id": 355, "title": "Взвешивания и переливания: уровень 3", "ico": "⚖️", "src": "Начальная школа · 3 класс · Олимп-3: взвешивания", "subj": "jun", "explain": ["9 монет, одна фальшивая (легче). Делим на 3 кучки по 3 и взвешиваем две кучки.", "Если весы равны — фальшивая в третьей кучке; если нет — в более лёгкой.", "Теперь у нас 3 монеты: взвешиваем две — лёгкая найдена. Итого 2 взвешивания!", "Переливания: бидон 7 л и банка 3 л. Наполним 7 л, отольём 3 л — останется ровно 4 л."], "check": {"q": "Из 9 монет (одна легче) сколько взвешиваний нужно гарантированно?", "choices": ["2", "1", "3", "4"], "ans": 0, "exp": "Сначала 3 кучки по 3 (1 взвешивание), потом 2 монеты из лёгкой тройки — всего 2."}, "tasks": [{"q": "В кучке 3 монеты, одна лёгкая. Сколько нужно взвешиваний?", "kind": "unit", "ans": 1, "tol": 0, "hints": ["Взвесь две монеты.", "Если равны — лёгкая третья: хватает 1 взвешивания."], "sol": "1"}, {"q": "Бидон 7 л и банка 3 л. Как отмерить 4 л?", "kind": "choice", "choices": ["наполнить 7 л и отлить 3 л", "наполнить банку дважды", "это невозможно", "налить 3 л и добавить 1 л"], "ans": 0, "tol": 0, "hints": ["7 − 3 = 4.", "Отлили 3 л — в бидоне осталось 4 л."], "sol": "наполнить 7, отлить 3"}]},
{"id": 356, "title": "Делимость: признаки 2, 3, 5, 9, 10", "ico": "➗", "src": "Начальная школа · 3 класс · Олимп-3: признаки делимости", "subj": "jun", "explain": ["На 2 делятся числа с последней чётной цифрой: 34, 128…", "На 5 — с цифрой 0 или 5 на конце; на 10 — с нулём.", "На 3 — если сумма цифр делится на 3: 321 → 3+2+1 = 6 ✓.", "На 9 — если сумма цифр делится на 9: 126 → 1+2+6 = 9 ✓."], "check": {"q": "Делится ли 414 на 3?", "choices": ["да", "нет"], "ans": 0, "exp": "4 + 1 + 4 = 9, а 9 делится на 3 → делится (414 : 3 = 138)."}, "tasks": [{"q": "Какую цифру поставить вместо * в числе 51*, чтобы оно делилось на 10?", "kind": "unit", "ans": 0, "tol": 0, "hints": ["На 10 делятся числа с нулём на конце.", "* = 0."], "sol": "0"}, {"q": "Какое число делится на 9?", "kind": "choice", "choices": ["123", "126", "128", "130"], "ans": 1, "tol": 0, "hints": ["Считаем сумму цифр.", "1+2+6 = 9 → 126 : 9 = 14."], "sol": "126"}]},
{"id": 357, "title": "Правило суммы и произведения: дерево вариантов", "ico": "🌳", "src": "Начальная школа · 3 класс · Олимп-3: комбинаторика", "subj": "jun", "explain": ["Из города А в Б ведут 2 дороги, из Б в В — 3. Сколько маршрутов А→Б→В? 2 · 3 = 6.", "Это правило произведения: выборы перемножаем.", "Если нужно выбрать ОДИН предмет из двух групп — складываем: 2 красных или 3 синих шара → 2 + 3 = 5 способов.", "Дерево вариантов помогает не потерять ни одного маршрута."], "check": {"q": "В кафе 3 супа и 4 вторых блюда. Сколько обедов «суп + второе»?", "choices": ["7", "12", "3", "4"], "ans": 1, "exp": "3 · 4 = 12 обедов."}, "tasks": [{"q": "Из А в Б — 2 дороги, из Б в В — 3. Сколько маршрутов А→Б→В?", "kind": "unit", "ans": 6, "tol": 0, "hints": ["Умножаем выборы.", "2 · 3 = 6."], "sol": "6"}, {"q": "В коробке 2 красных и 3 синих шара. Сколькими способами выбрать ОДИН шар?", "kind": "choice", "choices": ["5", "6", "2", "3"], "ans": 0, "tol": 0, "hints": ["Выбор «или» — складываем.", "2 + 3 = 5 способов."], "sol": "5"}]},
{"id": 358, "title": "Геометрия на клетках: периметр и разрезания", "ico": "▦", "src": "Начальная школа · 3 класс · Олимп-3: клетки", "subj": "jun", "explain": ["Площадь фигуры из клеток — число клеток внутри.", "Периметр — длина границы: у прямоугольника 4×2 клетки периметр = (4+2)·2 = 12 сторон клеток.", "Разрезания: прямоугольник 3×5 можно разрезать на 15 клеток-квадратиков 1×1.", "Считай по частям: большие фигуры разбивай на прямоугольники."], "check": {"q": "Прямоугольник 4×2 клетки. Его площадь?", "choices": ["6", "8", "4", "12"], "ans": 1, "exp": "4 · 2 = 8 клеток."}, "tasks": [{"q": "Квадрат 3×3 клетки. Чему равен периметр (в сторонах клеток)?", "kind": "unit", "ans": 12, "tol": 0, "hints": ["Сторона — 3 клетки.", "3 · 4 = 12."], "sol": "12"}, {"q": "Прямоугольник 3×5 разрезали на квадратики 1×1. Сколько квадратиков?", "kind": "choice", "choices": ["8", "15", "16", "10"], "ans": 1, "tol": 0, "hints": ["Площадь = число квадратиков.", "3 · 5 = 15."], "sol": "15"}]},
{"id": 359, "title": "Конструктивы: спички и танграм", "ico": "🧩", "src": "Начальная школа · 3 класс · Олимп-3: конструктивы", "subj": "jun", "explain": ["Из 4 спичек складываем квадрат — у квадрата 4 стороны.", "Из 5 спичек можно сложить два треугольника с общей стороной: 3 + 3 − 1 = 5.", "Танграм — древняя головоломка из 7 фигур, из которых складывают квадрат и разные фигуры.", "Конструктивы учат видеть общие части и перекладывать, а не ломать."], "check": {"q": "Сколько спичек нужно, чтобы сложить квадрат?", "choices": ["4", "3", "5", "6"], "ans": 0, "exp": "У квадрата 4 стороны — 4 спички."}, "tasks": [{"q": "Из скольких фигур состоит танграм?", "kind": "unit", "ans": 7, "tol": 0, "hints": ["Танграм — классическая головоломка.", "Из 7 фигур."], "sol": "7"}, {"q": "Из 5 спичек сложили два треугольника с общей стороной. Сколько спичек — общая сторона?", "kind": "choice", "choices": ["1", "2", "3", "0"], "ans": 0, "tol": 0, "hints": ["5 = 3 + 3 − 1.", "Общая сторона — одна спичка."], "sol": "1"}]}
]);